set +e
# stock1-undo (generated by make_guests.py from block-*.py; see those files for what and why)
fsck.hfsplus -f -n /dev/vda | tail -2
mount -t hfsplus -o rw,force /dev/vda /work/root || exit 1
python3 - <<'GUEST'
UNDO=True
# stock1: the 32 removable stock apps of 20H392 (Calculator, Calendar, Clock, Weather, Notes, Mail, Maps, Music, Files, Health,
# Wallet, FaceTime, Contacts, Reminders, Stocks, ...) ship in /private/var/staged_system_apps and are normally installed by the
# SystemAppMigrator data migrator on the first boot. The port skips data migration (LastSystemVersion=20H392 in
# com.apple.migration.plist, see NOTES v12) so they were never installed: containers/Bundle/Application is empty and
# installd logs 'System App Migration is complete' with 0 items. This block moves each staged bundle into /Applications
# (same volume: rename, 0 extra bytes), makes it root-owned like the other system apps (app dir root:admin 0775), and moves
# the LaunchServices caches aside so lsd/installd re-register /Applications at the next boot (proven by guest-install.sh,
# Terraria/Subway Surfers). Receipt /private/var/db/nord2-stock/stock1.json keeps the original owners for the undo.
# Idempotent; any unexpected state stops the block without further changes (STOCK1_REFUSED).
import os, json, glob, plistlib
R='/work/root'
S='/private/var/staged_system_apps'; A='/Applications'; D='/private/var/db/nord2-stock'; REC=D+'/stock1.json'
LSG='/private/var/mobile/Containers/Data/InternalDaemon/*/Library/Caches/*LaunchServices-*.csstore'
def bid(p):
    try: return plistlib.load(open(p+'/Info.plist','rb')).get('CFBundleIdentifier')
    except Exception: return None
def lsaside(tag):
    moved=[]
    for f in glob.glob(R+LSG):
        dst=f+'.'+tag
        if os.path.lexists(dst): os.remove(dst)
        os.rename(f,dst); moved.append(os.path.basename(f))
    return moved
def owners(top):
    out={}
    for base,dirs,files in os.walk(top):
        for n in ['']+dirs+files:
            p=os.path.join(base,n) if n else base
            if n=='' and base!=top: continue
            st=os.lstat(p); out.setdefault('%d:%d'%(st.st_uid,st.st_gid),[]).append(os.path.relpath(p,top))
    return out
def chown_tree(top,uid,gid):
    for base,dirs,files in os.walk(top):
        for n in dirs+files: os.lchown(os.path.join(base,n),uid,gid)
    os.lchown(top,uid,gid)
st=os.statvfs(R); free=st.f_bavail*st.f_frsize//2**20; print('STOCK1_FREE_MB',free)
rec=json.load(open(R+REC)) if os.path.exists(R+REC) else {'apps':{},'by':'payload-stock1'}
if not UNDO:
    plan=json.load(open('/src/plan.json'))['stock1']
    have={bid(p):os.path.basename(p) for p in glob.glob(R+A+'/*.app')}
    moved=[]; ok=True
    if free<64: print('STOCK1_REFUSED less than 64 MiB free'); ok=False
    for name,want in sorted(plan['apps'].items()):
        if not ok: break
        src,dst=R+S+'/'+name,R+A+'/'+name
        if os.path.isdir(dst) and not os.path.lexists(src) and name in rec['apps']: continue
        if not os.path.isdir(src) or os.path.lexists(dst) or bid(src)!=want or (want in have and have[want]!=name):
            print('STOCK1_REFUSED %s: src %s dst %s id %s'%(name,os.path.isdir(src),os.path.lexists(dst),bid(src))); ok=False; break
        st0=os.lstat(src); own=owners(src)
        os.rename(src,dst); chown_tree(dst,0,0); os.chown(dst,0,80); os.chmod(dst,0o775)
        rec['apps'][name]={'id':want,'owners':own if len(own)>1 else list(own)[0],'mode':st0.st_mode&0o7777}
        moved.append(name)
        os.makedirs(R+D,exist_ok=True); os.chmod(R+D,0o755)
        json.dump(rec,open(R+REC+'.tmp','w')); os.replace(R+REC+'.tmp',R+REC)   # receipt after every app
    ls=lsaside('pre-stock1') if moved else []
    print('STOCK1_INSTALL moved=%d %s ls_caches_aside=%s'%(len(moved),moved,ls))
else:
    back=[]
    for name,info in sorted(rec['apps'].items()):
        src,dst=R+A+'/'+name,R+S+'/'+name
        if os.path.isdir(src) and not os.path.lexists(dst) and bid(src)==info['id']:
            os.rename(src,dst)
            own=info['owners']
            if isinstance(own,str):
                u,g=map(int,own.split(':')); chown_tree(dst,u,g)
            else:
                for ug,paths in own.items():
                    u,g=map(int,ug.split(':'))
                    for rel in paths: os.lchown(os.path.normpath(os.path.join(dst,rel)),u,g)
            os.chmod(dst,info['mode']); back.append(name); del rec['apps'][name]
        elif os.path.isdir(dst) and not os.path.lexists(src): del rec['apps'][name]
        else: print('STOCK1_UNDO_SKIPPED %s (src %s dst %s)'%(name,os.path.isdir(src),os.path.lexists(dst)))
    if rec['apps']: json.dump(rec,open(R+REC,'w'))
    elif os.path.exists(R+REC): os.remove(R+REC)
    if os.path.isdir(R+D) and not os.listdir(R+D): os.rmdir(R+D)
    ls=lsaside('pre-stock1-undo') if back else []
    print('STOCK1_UNDO moved_back=%d %s ls_caches_aside=%s'%(len(back),back,ls))
os.sync()
GUEST
echo 'CC_JOB_ADDED stock1-undo'
echo 'CC_RECEIPT_UPDATED unchanged'
sync
umount /work/root
fsck.hfsplus -f -n /dev/vda
echo INSTALL_DONE
